CREATE TABLE IF NOT EXISTS businesses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,name VARCHAR(120) NOT NULL);
CREATE TABLE IF NOT EXISTS quotes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner_id BIGINT NOT NULL REFERENCES businesses(id),customer VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,address VARCHAR(500) NOT NULL,title VARCHAR(160) NOT NULL,notes VARCHAR(2000) NOT NULL,discount DECIMAL(12,2) NOT NULL,tax DECIMAL(5,2) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,expires DATE NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',token VARCHAR(64) UNIQUE,feedback VARCHAR(2000) NOT NULL DEFAULT '',reviewer VARCHAR(120) NOT NULL DEFAULT '',created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,responded TIMESTAMP,job_date DATE,job_stage VARCHAR(30) NOT NULL DEFAULT 'UNSCHEDULED');
CREATE TABLE IF NOT EXISTS quote_lines (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,quote_id BIGINT NOT NULL REFERENCES quotes(id),description VARCHAR(200) NOT NULL,quantity DECIMAL(8,2) NOT NULL,price DECIMAL(10,2) NOT NULL,amount DECIMAL(12,2) NOT NULL);
CREATE INDEX IF NOT EXISTS quote_owner_idx ON quotes(owner_id);
